const ahora = new Date();
const ts = Date.now();

return [
  {
    json: {
      id_ejecucion: 'CERT-SIN-' + ts,
      id_incidente: 'INC-CERT-' + ts,
      flujo: '02',
      proceso: 'certificados',
      escenario: 'sin_seguridad',
      bloque: 'sin_seguridad',
      remitente_email: 'estudiante.prueba@instituto.edu.pe',
      asunto: 'Solicitud de certificado de estudios',
      cuerpo: 'Solicito mi certificado de estudios correspondiente al periodo académico actual.',
      hora_ingreso: ahora.toISOString().slice(0, 19).replace('T', ' ')
    }
  }
];

return items.map(item => {
  const texto = `${item.json.asunto || ''} ${item.json.cuerpo || ''}`.toLowerCase();

  let tipo = 'no_identificado';

  if (texto.includes('estudios')) {
    tipo = 'estudios';
  } else if (texto.includes('notas')) {
    tipo = 'notas';
  } else if (texto.includes('egresado')) {
    tipo = 'egresado';
  }

  item.json.tipo_certificado = tipo;
  item.json.estado_certificado = 'pendiente';
  item.json.categoria_sistema = tipo;
  item.json.categoria_real = tipo;
  item.json.clasificacion_correcta = true;
  item.json.hora_procesamiento = new Date()
    .toISOString()
    .slice(0, 19)
    .replace('T', ' ');

  return item;
});
